package com.aiot.log.dto; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalTime;
public class EnvironmentAnnouncementRuleRequest { @NotNull public Long spaceId; @NotBlank public String name; @NotBlank @Pattern(regexp="temperature|aqi|precipitation|weather_change|indoor_temperature|indoor_humidity|indoor_pressure|indoor_illuminance") public String metric; @DecimalMin("0") public BigDecimal changeValue; @DecimalMin("0") public BigDecimal thresholdValue; @Min(1) @Max(10) public Integer consecutiveCount=2; @Min(1) @Max(1440) public Integer cooldownMinutes=60; public LocalTime quietStart=LocalTime.of(22,30); public LocalTime quietEnd=LocalTime.of(7,30); public Boolean enabled=true; }
